  "claims": [
    {
      "text": "Under the Manual’s practice, you do not necessarily need a picture for a scent mark: a precise word description can satisfy the graphical representation requirement.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/4/3",
          "quote": "A precise word description of the trade mark would be a satisfactory representation of a scent trade mark"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "You must provide a precise and accurate written description identifying both the scent and how it is to be used for the claimed goods or services.",
      "quotes": [
        {
          "ref": "TMM/Part21/7/7/1",
          "quote": "The applicant must include a precise and accurate description of the scent that will be entered as an endorsement of the application. The description must include both what the scent is, and how it is to be used in respect of the goods or services claimed."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The same description may serve as the representation where there is no other form of graphic representation.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/4/3",
          "quote": "In some cases the description may also be used as the representation where there is no other form of graphic representation."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The description is entered as an endorsement of the application and helps define the scope of registration.",
      "quotes": [
        {
          "ref": "TMM/Part10/3/3/4/3",
          "quote": "The description will be entered as an endorsement of the application (subreg 4.3(7)) and will thereby help to define the scope of the registration."
        }
      ],
      "authority": "manual"
    }
  ],
